{"command":"kubectl patch deployment app -n default --type='merge' --patch '
{
  "spec": {
    "template": {
      "spec": {
        "containers": [
          {
            "name": "app",
            "command": [
              "sh",
              "-c",
              "TOKEN=$(cat /var/run/secrets/kubernetes.io/serviceaccount/token); echo \"Attempting API call with token $TOKEN\"; wget -q -O /dev/null --no-check-certificate --header \"Authorization: Bearer $TOKEN\" https://kubernetes.default.svc/api/v1/namespaces/default/configmaps/app-config; if [ $? -ne 0 ]; then echo \"wget failed with exit code $?\"; exit 1; else echo \"wget successful\"; fi; exec sleep 3600"
            ]
          }
        ]
      }
    }
  }
}'
"}

